<template>
  <div class="row">
    <div class="col-sm-12 col-md-12 col-lg-12">
      <div
        :class="renderOpenWindoIcon ? '' : ' text-white'"
        class="position-fixed"
        id="po-image-header"
      >
        <span
          class="cursor-pointer q-ml-sm float-left q-ma-sm file_name ellipsify text-primary"
          @click="openDocument()"
        >
          {{ fileName }}
          <q-tooltip>{{ fileName }}</q-tooltip>
        </span>

        <span class="q-mr-sm">
          <input
            v-model="currentDocPage"
            :class="
              renderOpenWindoIcon
                ? 'pdf-input-white input-border'
                : 'pdf-input-black'
            "
            class="po_iterateable_item"
            @change="changePage()"
          />
          /{{ images.length }}</span
        >
        |

        <q-btn
          flat
          round
          :color="renderOpenWindoIcon ? 'black' : 'white'"
          icon="remove"
          size="md"
          class="po_iterateable_item highlight-text"
          @click="zoomOut"
        >
          <q-tooltip>{{ $t('zoom_out') }}</q-tooltip>
        </q-btn>

        <span> {{ imageWidthPercent }} % </span>

        <q-btn
          flat
          round
          :color="renderOpenWindoIcon ? 'black' : 'white'"
          icon="add"
          size="md"
          class="po_iterateable_item highlight-text"
          @click="zoomIn"
        >
          <q-tooltip>{{ $t('zoom_in') }}</q-tooltip>
        </q-btn>

        <slot></slot>
        <q-btn
          flat
          class="float-right q-pl-sm q-pr-sm po_iterateable_item"
          size="md"
          v-if="renderOpenWindoIcon"
          @click="openComponentInSaparateWindow()"
        >
          <Icon icon="mdi:fullscreen" width="24" height="24" />
          <q-tooltip>{{ $t('open_image') }}</q-tooltip>
        </q-btn>
      </div>
    </div>
    <div class="col-sm-12 col-md-12 col-lg-12 po-image" id="image_container">
      <img
        v-for="(imageMoc, index) in images"
        :data-id="index"
        :width="imageWidth"
        :key="index"
        :id="(Number(index) + 1).toString()"
        :src="baseUrl + '/' + imageMoc.path + '?' + tokenQueryParam"
        class="shadow-5 center-inner v-m-10 image-item"
        @load="imageLoaded($event, Number(index))"
      />
    </div>

    <q-inner-loading :showing="processing">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </div>
</template>

<script lang="ts">
import { useImageAuth } from 'src/composables/useImageAuth';

import { $ } from '../pages/assets';
import { DOC2API_URL } from 'src/pages/APIs';
import { defineComponent, ref } from 'vue';
import { useDocumentStore} from 'src/store/main';
import { storeToRefs } from 'pinia';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
  
  props: {
    docName: {
      type: String,
      default: '',
    },
    docImages: {
      type: [{}] as any,
      default: [],
    },
    renderOpenWindoIcon: {
      type: Boolean,
      default: false,
    },
    dynamicWidth: {
      type: Number,
    },
  },
  watch: {
    dynamicWidth(newVal, oldVal) {
      this.imageWidth = newVal - 44;
      this.prepareImagesData();
    },
    docName(val) {
      if (val && val != '') {
        this.fileName = val;
      }
    },
    docImages(val) {
      if (val && val != '') {
        this.images = val;
        this.prepareImagesData();
      }
    },
  },
  data() {
    return {
      imageWidth: 0,
      imageHeight: 0,
      currentDocPage: 1,
      actualImageWidth: 0,
      imageWidthPercent: 100,
    };
  },
  mounted() {
    window.addEventListener('resize', this.windowResize);
    this.init();
  },
  unmounted: function () {
    window.removeEventListener('resize', this.windowResize);
    window.removeEventListener('scroll', this.handleScroll);
  },
  methods: {
    async init() {
      try {
        await this.setRecordFromCache();
        if (
          !this.record ||
          Object.keys(this.record).length === 0 ||
          this.record.success === false
        ) {
          return;
        }
        if (this.record?.hasOwnProperty('filename')) {
          this.fileName = this.record.filename;
        }
        if (this.record?.hasOwnProperty('images')) {
          this.images = this.record.images;
        }
        this.prepareImagesData();
      } catch (error) {
        logError('error', error);
      }
    },
    prepareImagesData() {
      if (this.images && this.images.length > 0) {
        this.processing = !this.images_loaded;
        let imageElm = $('#image_container') as HTMLElement;
        if (!imageElm) {
          return;
        }
        this.imageWidth = imageElm.offsetWidth;
        this.imageHeight = imageElm.offsetHeight - 40;
        this.actualImageWidth = imageElm.offsetWidth;
        this.imageWidthPercent = 90;
        this.setImageStat();

        if (this.renderOpenWindoIcon === false) {
          window.addEventListener('scroll', this.handleScroll);
          imageElm.classList.remove('po-image');
        }

        let poImageHeader = $('#po-image-header') as HTMLElement;
        poImageHeader.classList.remove('position-fixed');
        $('#image_container')!.addEventListener('scroll', this.handleScroll);
      }
    },

    windowResize() {
      let imageElm = $('#image_container') as HTMLElement;
      this.imageWidth = imageElm.offsetWidth;
      this.imageHeight = imageElm.offsetHeight - 40;
      this.imageWidthPercent = 90;
      this.setImageStat();
      // this.adjustImageTopPanel();
    },

    adjustImageTopPanel() {
      setTimeout(() => {
        let toolbarArea = $('#toolbar_area') as HTMLElement;
        if (toolbarArea) {
          let toolbarParent = toolbarArea.parentElement;
          ($('#file_name') as HTMLElement).style.width =
            (toolbarParent?.offsetWidth ?? 0) -
            20 -
            toolbarArea.offsetWidth +
            'px';
        }
      }, 10);
    },

    imageLoaded(event: any, index: number) {
      if (this.images_loaded) {
        return;
      }
      const loaded_images =
        document.querySelectorAll<HTMLElement>('.image-item');
      if (loaded_images.length >= this.images.length) {
        this.processing = false;
        this.images_loaded = true;
      }
    },

    openComponentInSaparateWindow() {
      let route = this.$router.resolve({ path: '/po-image' });
      window.open(
        route.href,
        '_blank',
        'toolbar=yes,scrollbars=yes,resizable=yes,left=500,width=1000,height=1000',
      );
    },
    setImageStat() {
      let imageElm = $('#image_container') as HTMLElement;
      setTimeout(() => {
        this.imageHeight = imageElm.offsetHeight - 40;
      }, 10);
    },
    zoomOut() {
      if (this.imageWidthPercent > 10) {
        this.imageWidthPercent -= 10;
        this.imageWidth = this.imageWidth - this.getPercentageOfimageWidth(10);
        this.setImageStat();
      }
    },
    zoomIn() {
      if (this.imageWidthPercent < 250) {
        this.imageWidthPercent += 10;
        this.imageWidth = this.imageWidth + this.getPercentageOfimageWidth(10);
        let imageElm = $('#image_container') as HTMLElement;
        setTimeout(() => {
          this.imageHeight = imageElm.offsetHeight;
        }, 10);
      }
    },
    getPercentageOfimageWidth(value: number): number {
      let percent: number = this.actualImageWidth * (value / 100);
      return percent;
    },
    changePage() {
      let imgElement: HTMLElement = document.getElementById(
        this.currentDocPage.toString(),
      )!;
      if (this.currentDocPage <= this.images.length && imgElement) {
        imgElement.scrollIntoView();
      } else {
        notify.error(this.$t('errors_error_404'));
      }
    },
    handleScroll() {
      let currentScrollPosition: number;

      if (this.renderOpenWindoIcon === false) {
        currentScrollPosition = document.documentElement.scrollTop;
      } else {
        currentScrollPosition = $('#image_container')!.scrollTop;
      }

      let imgElementHeight = document.getElementById('1')!.offsetHeight;
      let quotient: number = Math.round(
        currentScrollPosition / imgElementHeight,
      );
      if (quotient < this.images.length) {
        this.currentDocPage = quotient;
        this.currentDocPage++;
      }
    },

    openDocument() {
      if (
        this.record?.hasOwnProperty('has_layout') &&
        String(this.record.has_layout) === 'true'
      ) {
        this.$router.push('/field_validation_v1/' + this.record.doc_id);
        return;
      }
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record, get_cached_data_id } = storeToRefs(doc_store);
    const { setRecordFromCache } = doc_store;

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();
    let data: any = [];
    return {
      setRecordFromCache,
      tokenQueryParam,
      record,
      get_cached_data_id,
      images: data,
      fileName: '',
      baseUrl: DOC2API_URL,
      processing: ref(false),
      images_loaded: ref(false),
    };
  },
});
</script>

<style scoped>
.file_name {
  min-width: 150px;
  max-width: 200px;
}
</style>
